<?php
declare(strict_types=1);
session_start();
$config = require dirname(__DIR__) . '/config.php';
try {
    $pdo = new PDO($config['dsn'], $config['db_user'], $config['db_password'], [PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC, PDO::ATTR_EMULATE_PREPARES=>false]);
} catch (Throwable $e) { http_response_code(500); exit('Database connection unavailable. Check config.php.'); }
function h(?string $s): string { return htmlspecialchars((string)$s, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
function csrf_token(): string { if (empty($_SESSION['csrf'])) $_SESSION['csrf']=bin2hex(random_bytes(32)); return $_SESSION['csrf']; }
function check_csrf(): void { if (!hash_equals($_SESSION['csrf'] ?? '', (string)($_POST['csrf'] ?? ''))) { http_response_code(400); exit('Invalid request token. Refresh and try again.'); } }
function require_login(): array {
    global $pdo;
    if (empty($_SESSION['admin_id'])) { header('Location: login.php'); exit; }
    $q=$pdo->prepare('SELECT u.id,u.full_name,u.email,u.is_active,r.id role_id,r.role_key,r.display_name FROM admin_users u JOIN roles r ON r.id=u.role_id WHERE u.id=?');
    $q->execute([$_SESSION['admin_id']]); $user=$q->fetch();
    if (!$user || !$user['is_active']) { $_SESSION=[]; session_destroy(); header('Location: login.php'); exit; }
    $q=$pdo->prepare('SELECT p.permission_key FROM role_permissions rp JOIN permissions p ON p.id=rp.permission_id WHERE rp.role_id=?'); $q->execute([$user['role_id']]);
    $user['permissions']=array_column($q->fetchAll(),'permission_key');
    return $user;
}
function need(string $permission): array { $u=require_login(); if (!in_array($permission,$u['permissions'],true)) { http_response_code(403); exit('You do not have permission to access this page.'); } return $u; }
